// src/github-copilot/responses/tool/file-search.ts
import { createProviderToolFactoryWithOutputSchema } from "@ai-sdk/provider-utils";
import { z } from "zod/v4";
var comparisonFilterSchema = z.object({
  key: z.string(),
  type: z.enum(["eq", "ne", "gt", "gte", "lt", "lte"]),
  value: z.union([z.string(), z.number(), z.boolean()])
});
var compoundFilterSchema = z.object({
  type: z.enum(["and", "or"]),
  filters: z.array(z.union([comparisonFilterSchema, z.lazy(() => compoundFilterSchema)]))
});
var fileSearchArgsSchema2 = z.object({
  vectorStoreIds: z.array(z.string()),
  maxNumResults: z.number().optional(),
  ranking: z.object({
    ranker: z.string().optional(),
    scoreThreshold: z.number().optional()
  }).optional(),
  filters: z.union([comparisonFilterSchema, compoundFilterSchema]).optional()
});
var fileSearchOutputSchema2 = z.object({
  queries: z.array(z.string()),
  results: z.array(z.object({
    attributes: z.record(z.string(), z.unknown()),
    fileId: z.string(),
    filename: z.string(),
    score: z.number(),
    text: z.string()
  })).nullable()
});
var fileSearch2 = createProviderToolFactoryWithOutputSchema({
  id: "openai.file_search",
  inputSchema: z.object({}),
  outputSchema: fileSearchOutputSchema2
});

export { fileSearchArgsSchema2, fileSearchOutputSchema2, fileSearch2 };
